#!/home/zhongming/.venvs/codenib/bin/python
"""Isolated registration stand-in: no agent process or real profile access."""
import json
import os
import sys
from pathlib import Path
state = Path(os.environ['CODENIB_FIXTURE_CLIENT_STATE'])
rows = json.loads(state.read_text()) if state.exists() else {}
args = sys.argv[1:]
if args[:2] == ['mcp', 'get']:
    name = args[-1]
    if name not in rows:
        print('No MCP server named ' + name, file=sys.stderr)
        sys.exit(1)
    print(json.dumps(rows[name]))
elif args[:2] == ['mcp', 'add']:
    name = args[2]
    command = args[args.index('--') + 1:]
    rows[name] = {'name': name, 'enabled': True, 'transport': {'type': 'stdio', 'command': command[0], 'args': command[1:]}}
    state.write_text(json.dumps(rows))
elif args[:2] == ['mcp', 'remove']:
    rows.pop(args[2], None)
    state.write_text(json.dumps(rows))
else:
    sys.exit('fixture only supports mcp get/add/remove')
